CHAPTERS = {
  1: ('Перед {event} {name} пересчитал кассу. {income} ещё не покрывали {cost}; денег на всё сразу не было. Он записал доходы и расходы в бюджет и отложил необязательную покупку. Вечером выяснилось, что наличные придётся передать другому участнику команды.', 'Бюджет помогает увидеть, на что хватит денег до покупки.'),
  2: ('Для оплаты {cost} {name} достал дебетовую карту. Друг подумал, что сумма хранится в пластике, но {name} открыл приложение и показал остаток на счёте. После платежа баланс уменьшился. Теперь команда искала способ накопить на ещё одну нужную вещь.', 'Карта даёт доступ к деньгам на счёте; платёж уменьшает остаток.'),
  3: ('К {event} нужен комплект за 20 000 ₽. {name} может откладывать по 3 000 ₽ в месяц на накопительный счёт. Без процентов понадобится семь взносов. Банк указывает 12% годовых, но точное начисление зависит от дат пополнения и условий. Продавец предложил забрать комплект раньше — хватит ли денег?', 'Годовую ставку нельзя считать как месячный доход; срок зависит от пополнений.'),
  4: ('Перед {event} друг уверял, что вклад 10 000 ₽ под 10% даст 1 000 ₽ уже завтра. {name} заметил слово «годовых»: при простом расчёте такая прибавка получится лишь за полный год. Сбережения команды нужны раньше. За столом появился другой вариант — оплатить покупку частями.', '10% годовых от 10 000 ₽ — это 1 000 ₽ за полный год при заданных условиях.'),
  5: ('Перед {event} оборудование сломалось. Продавец предложил кредит с небольшим ежемесячным платежом. {name} сложил все платежи и увидел переплату. Команда выбрала аренду для события, сохранив деньги на будущую покупку. Утром поставщик сообщил, что цены на материалы изменились.', 'Стоимость кредита оценивают по всем платежам и переплате.'),
  6: ('Год назад материалы стоили 10 000 ₽. При учебном росте общего уровня цен на 10% такая корзина теперь стоила бы 11 000 ₽. {name} объяснил: инфляция уменьшает покупательную способность той же суммы; одна подорожавшая вещь сама по себе её не доказывает. После {event} у команды остались деньги — что с ними делать?', 'При росте общего уровня цен прежняя сумма покупает меньше.'),
  7: ('После {event} осталось 10 000 ₽. {name} посчитал: при условных 10% годовых и ежегодной капитализации через три года получилось бы 13 310 ₽. Сложный процент начисляется и на прежние проценты. Это расчёт, а не обещание реальной ставки. Друг показал акцию компании, цена которой росла всю неделю.', 'Капитализация увеличивает базу для следующего начисления процентов.'),
  8: ('Друг хотел вложить все деньги в акцию перед {event}. {name} проверил: цена на бирже может снизиться, а дивиденд не гарантирован. Команда оставила деньги на ближайшие расходы и купила акцию только в учебном симуляторе. Тогда друг нашёл облигацию с купоном выше банковской ставки.', 'Акция даёт долю в компании, но не гарантирует рост цены и дивиденды.'),
  9: ('Облигация обещала купон, однако погашение наступало после {event}. {name} сравнил цену покупки, выплаты и возможную доходность: эмитент должен выполнить условия, но риск невыплаты остаётся. Деньги понадобятся раньше. На следующий день котировка резко изменилась.', 'Доходность облигации зависит от условий, цены покупки и риска.'),
  10: ('Цена выбранного актива скакала перед {event}. {name} назвал это волатильностью и сопоставил риск с коротким горизонтом инвестирования: средства нужны скоро. Команда не стала рассчитывать на будущую цену. Друг предложил вложить долгосрочный запас сразу в одну компанию.', 'Срок цели помогает оценить, какой риск колебаний допустим.'),
  11: ('Друг предлагал купить один актив на все свободные деньги. {name} возразил: диверсификация снижает зависимость от одной компании, хотя не убирает все риски. Команда разделила долгосрочную часть между несколькими вложениями, а деньги на {cost} сохранила доступными. Как собрать их в один понятный план?', 'Разные активы могут снизить отдельные риски, но не гарантируют доход.'),
  12: ('После {event} {name} записал цель, срок и допустимый риск. Инвестиционный портфель включил разные активы; деньги на близкие расходы остались ликвидными. Команда сравнила результат с первым бюджетом и обнаружила, что самый полезный шаг был сделан ещё до выбора вложений.', 'Состав портфеля зависит от цели, срока, риска и потребности быстро получить деньги.'),
}


def render(lesson_id, character, scene):
    story, takeaway = CHAPTERS[lesson_id]
    _, income, cost, event = scene
    return story.format(name=character['name'], income=income, cost=cost, event=event), takeaway
